/**
 * [B16-C §5] Page-level browser proof of the prompt-to-Gerber flow against the
 * REAL Next.js application — not route handlers, not jsdom.
 *
 * The web server runs under the env-gated FIXTURE RUNTIME (see
 * app/lib/fixture-runtime/mode.ts): in-memory durable/binding stores, the
 * committed blinker catalog, the recorded provider design, the recorded
 * FreeRouting run replayed by placed-board revision, local-development
 * identity with a dev-only role cookie. No database, no credits, no live
 * router. Live provider/auth variations stay explicitly opt-in elsewhere.
 *
 *   pnpm exec playwright test            (starts `next dev` on port 3100)
 *   SIRKIT_FIXTURE_ROUTER=record …       (re-records e2e/fixtures/blinker-route-fixture.json with the bundled runtime)
 */
import { defineConfig, devices } from "@playwright/test";

const PORT = Number(process.env.SIRKIT_E2E_PORT ?? 3100);

export default defineConfig({
  testDir: "./e2e",
  testMatch: /.*\.spec\.ts/, testIgnore: (process.env.SIRKIT_E2E_SKIP ?? "").split(",").map((glob) => glob.trim()).filter(Boolean), // [B24-D4, 2026-10-10] OD-30's split: SIRKIT_E2E_SKIP, a comma-separated list of spec globs, leaves those specs out of a run (page-browser-e2e skips the four page-browser-e2e-b24 runs); unset or empty ignores nothing
  fullyParallel: false,
  workers: 1,
  retries: 0,
  timeout: 180_000,
  expect: { timeout: 20_000 },
  reporter: process.env.CI ? [["list"], ["junit", { outputFile: "playwright-report/junit.xml" }], ["html", { open: "never" }]] : [["list"], ["html", { open: "never" }]],
  // Failure artifacts (screenshots, traces, error context) live OUTSIDE the HTML reporter's folder:
  // the HTML reporter clears its own output directory, so a shared folder loses the evidence.
  outputDir: "test-results",
  use: {
    baseURL: `http://localhost:${PORT}`,
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    video: "off",
    // A FRESH browser: no storage, no cookies (each test creates its own context).
    storageState: { cookies: [], origins: [] },
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: {
    command: `pnpm exec next dev --port ${PORT}`,
    url: `http://localhost:${PORT}/api/ai/runtime`,
    reuseExistingServer: !process.env.CI,
    timeout: 240_000,
    stdout: "pipe",
    stderr: "pipe",
    env: {
      ...process.env,
      NODE_ENV: "development",
      SIRKIT_AUTH_MODE: "local_dev",
      SIRKIT_FIXTURE_RUNTIME: "blinker",
      SIRKIT_FIXTURE_ROUTER: process.env.SIRKIT_FIXTURE_ROUTER ?? "replay",
      // The Stage 3 synchronization rollout is OFF unless declared (the first CI run answered
      // PS_STAGE3_DISABLED 503 where the local .env.local had set it): the fixture runtime declares
      // the same state the deterministic pipelines use.
      SIRKIT_PCB_SYNC_STAGE3: "opt_in",
      // [B18-C I10] the chat route answers with the SCRIPTED agent (never a model): honoured only under the fixture runtime.
      SIRKIT_FIXTURE_AGENT: "scripted",
      // [B20 D3] the MCP endpoint, for the wire-level proof (e2e/mcp-endpoint.spec.ts). The flag must be exactly "1".
      // SIRKIT_EXPECTED_ORIGIN moves CSRF resolution from request-url-local-dev to `configured`; the value is exactly the
      // origin `baseURL` produces, so every existing spec's Origin still matches (the four pre-existing specs staying
      // green in the same run is the proof, not the argument). The secret is assembled from parts at run time, exceeds
      // the minimum byte length, and is an obvious fake that no real deployment would use.
      SIRKIT_MCP_ENABLED: "1",
      SIRKIT_EXPECTED_ORIGIN: `http://localhost:${PORT}`,
      SIRKIT_MCP_TOKEN_SECRET: ["e2e", "mcp", "token", "secret", "0123456789abcdef0123456789abcdef"].join("-"),
      // Never let a developer's .env.local database leak into the proof.
      DATABASE_URL: "",
    },
  },
});

playwright.orchestration.config.ts.text:
/**
 * [B21 F2] The ORCHESTRATION browser proof's own Playwright config (D21-43, the lead's decision): the SAME fixture web server as
 * `playwright.config.ts` - its command and its whole environment, imported, never copied - PLUS `SIRKIT_ORCHESTRATION_ENABLED=1` and the circuit specialist routed to anthropic (F6's second source), on
 * its own port, with its own test dir (`./e2e-orchestration`, outside `./e2e`: the existing suite and B18-E's browser proofs never
 * see the flag), its own report and output folders, workers 1, retries 0 and the same per-test timeout.
 *
 * The flag is read from the server's environment at REQUEST time (`orchestrationEnabled(process.env)`), so this server needs no
 * second dist dir as long as it never runs BESIDE the flag-off one: the two configs run ONE AFTER THE OTHER (locally through the
 * lead's lock script, in CI as one extra step after `pnpm exec playwright test`) - one `next dev` at a time, no `next.config.ts`
 * change. `reuseExistingServer: false`: this config never attaches to a running (flag-off) server; a busy port fails the run.
 *
 *   pnpm exec playwright test -c playwright.orchestration.config.ts        (starts the base's `next dev` on port 3101)
 */
import { defineConfig, devices } from "@playwright/test";
import base from "./playwright.config";

const PORT = Number(process.env.SIRKIT_E2E_ORCHESTRATION_PORT ?? 3101);
const ORIGIN = `http://localhost:${PORT}`;
const baseServer = base.webServer;
if (!baseServer || Array.isArray(baseServer)) throw new Error("playwright.config.ts must define ONE web server: the orchestration config runs the same one with the flag on");
// [B21 F2 fix: tests-05] the base's command and readiness url with ONLY their port moved to this config's (a base change reaches this server)
const BASE_URL = new URL(String(baseServer.url)); const BASE_PORT = BASE_URL.port || (BASE_URL.protocol === "https:" ? "443" : "80"); const BASE_PORT_FLAG = new RegExp(`--port ${BASE_PORT}(?![0-9])`); // [B21 F2 lead] a default port (the URL omits it) is still the flag's, and never a prefix of a longer port
if (typeof baseServer.command !== "string" || !BASE_PORT_FLAG.test(baseServer.command)) throw new Error(`playwright.config.ts's web server command must carry "--port ${BASE_PORT}": the orchestration config runs that command on its own port`);

export default defineConfig({
  testDir: "./e2e-orchestration",
  testMatch: /.*\.spec\.ts/,
  fullyParallel: false,
  workers: 1,
  retries: 0,
  timeout: base.timeout,
  expect: base.expect,
  reporter: process.env.CI ? [["list"], ["junit", { outputFile: "playwright-report-orchestration/junit.xml" }], ["html", { open: "never", outputFolder: "playwright-report-orchestration" }]] : [["list"], ["html", { open: "never", outputFolder: "playwright-report-orchestration" }]],
  // Failure artifacts live outside the HTML reporter's folder (it clears its own output directory), as in the base config.
  outputDir: "test-results-orchestration",
  use: { ...base.use, baseURL: ORIGIN },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: {
    ...baseServer,
    command: baseServer.command.replace(BASE_PORT_FLAG, `--port ${PORT}`),
    url: `${ORIGIN}${BASE_URL.pathname}${BASE_URL.search}`,
    reuseExistingServer: false,
    env: {
      ...baseServer.env,
      // the base config's origin is its own port's: CSRF resolves against THIS server's origin
      SIRKIT_EXPECTED_ORIGIN: ORIGIN,
      // the flag: the chat route's DAG path (exactly "1")
      SIRKIT_ORCHESTRATION_ENABLED: "1",
      // [B21 F2 fix: security-1] F6's two parties on TWO providers, as b21-f-evaluation case 6 routes them: the circuit specialist on anthropic, every other role on the page's openai (the scripted agent serves both offline); set here, a developer's .env.local never re-routes a role
      SIRKIT_ORCHESTRATION_ROLE_MODELS: JSON.stringify({ "circuit-topology": { provider: "anthropic", model: "inherit" } }),
    },
  },
});

vitest.config.ts.text:
import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";

export default defineConfig({
  // tsconfig says jsx: "preserve" (Next's compiler owns it); vitest's esbuild
  // must transform JSX itself for .test.tsx files.
  esbuild: { jsx: "automatic" },
  resolve: {
    // Mirror tsconfig's "@/*" → "./*" so tests can exercise modules that use
    // the app-wide import alias.
    alias: { "@": fileURLToPath(new URL(".", import.meta.url)).replace(/[\\/]$/, "") },
  },
  test: {
    environment: "node",
    // Stage 17: .test.tsx files run component tests — they opt into jsdom
    // with a `// @vitest-environment jsdom` docblock; .test.ts stays node.
    include: ["app/**/__tests__/**/*.test.{ts,tsx}"],
    setupFiles: ["./app/lib/qualification/__tests__/_database-env-guard.ts"], // [B24-C1 review, 2026-10-08] no suite reaches a database the shell names: an ambient DATABASE_URL is removed before every test file
  },
});
